(async () => {
  const browser = await chromium.launch({ headless: true, executablePath: '/home/runner/.cache/ms-playwright/chromium_headless_shell-1243/chrome-headless-shell-linux64/chrome-headless-shell', args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  page.on('pageerror', e => console.log('PAGEERROR', String(e)));
  page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE', m.text()); });
  await page.goto('http://localhost:3002/index.html?debug=1');
  await page.click('#startGame');
  await page.waitForFunction(() => window.__game && __game.state().opening === false, { timeout: 30000 });
  if (await page.evaluate(() => document.querySelector('#dialogShade').classList.contains('open')))
    await page.evaluate(() => document.querySelector('#dialogChoices button').click());
  await page.waitForTimeout(300);
  await page.evaluate(() => {
    __game.tasks.breakfast = true;
    __game.tasks.showers = true;
    __game.tasks.laundry = true;
    __game.girls.filter(g => !g.dog).forEach(g => { g.speed = 190; g.mood = 85; g.history = 2; g.x = 200; g.y = 520; g.route = []; g.routeMode = ''; g.callStatus = ''; g.seatedAtTable = false; });
  });
  await page.evaluate(() => { __game.player.x = 400; __game.player.y = 520; __game.interact(); });
  await page.waitForTimeout(300);
  console.log('dialog', await page.evaluate(() => ({ open: document.querySelector('#dialogShade').classList.contains('open'), title: document.querySelector('#dialogTitle').textContent, text: document.querySelector('#dialogText').textContent })));
  for (let i = 0; i < 20; i++) {
    await page.waitForTimeout(1000);
    const info = await page.evaluate(() => ({
      paused: __game.state().paused,
      current: __game.state().currentCallTask,
      girls: __game.girls.map(g => ({ n: g.short, x: Math.round(g.x), y: Math.round(g.y), st: g.callStatus, seated: !!g.seatedAtTable, route: g.route && g.route.length, mode: g.routeMode, stuck: Math.round((g.stuckTime || 0) * 10) / 10, speed: g.speed, agenda: g.agenda }))
    }));
    console.log(i, JSON.stringify(info));
    if (info.girls.filter(g => !g.n.includes('Charlie')).every(g => g.seated)) { console.log('ALL SEATED'); break; }
  }
  await browser.close();
})();

