const { launch } = require('/home/runner/work/PlayGround/PlayGround/tests/browser');
(async () => {
  const browser = await launch();
  // Desktop: opening screen, then in-game with the wake dialog.
  let page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  await page.goto('http://localhost:3002/index.html');
  await page.waitForTimeout(400);
  await page.screenshot({ path: 'screenshots/final-intro.png' });
  await page.click('#startGame');
  await page.waitForFunction(() => window.__game === undefined || true);
  await page.waitForTimeout(2600);
  await page.screenshot({ path: 'screenshots/final-opening.png' });
  await page.close();

  // Mobile in-game.
  page = await browser.newPage({ viewport: { width: 390, height: 844 } });
  await page.goto('http://localhost:3002/index.html?debug=1');
  await page.waitForTimeout(300);
  await page.screenshot({ path: 'screenshots/final-mobile-intro.png' });
  await page.click('#startGame');
  await page.waitForTimeout(2600);
  await page.screenshot({ path: 'screenshots/final-mobile-game.png' });
  await page.close();
  await browser.close();
  console.log('screenshots saved');
})();

