```js
function yardActivityChoices(){
 const choices=[];
 if(girlsOutside&&!sandboxPlayed)choices.push({label:'Build a sandcastle together',run:()=>startSandcastleGame()});
 if(fetchUses<2)choices.push({label:'Play fetch with Charlie',run:()=>startFetchGame()});
 if(girlsOutside)choices.push({label:'Send the girls inside',run:()=>sendGirlsInside()});
 else choices.push({label:'Call the girls outside',run:()=>callGirlsOutside()});
 choices.push({label:'Close and keep moving',run:()=>{}});
 return choices;
}
