438: function openMiniGame(type){
439:  if($('dialogShade').classList.contains('open'))closeDialog();
440:  miniGame.active=true;miniGame.type=type;miniGame.phase=type==='sandcastle'?'drop':'play';miniGame.time=0;miniGame.last=performance.now();miniGame.closeToast='';
441:  miniShade.classList.add('open');miniShade.setAttribute('aria-hidden','false');
442:  miniKeys.clear();keys.clear();fitMiniCanvas();
443:  if(type==='sandcastle')setupSandcastle();else setupFetchGame();
444:  miniPrimary.style.display='';miniQuit.style.display='';
445:  miniPrimary.focus({preventScroll:true});
446:  cancelAnimationFrame(miniRaf);miniRaf=requestAnimationFrame(miniLoop);
447: }
448: function closeMiniGame(){
449:  if(!miniGame.active)return;
450:  const resultToast=miniGame.closeToast;
451:  miniGame.active=false;miniGame.type='';miniGame.phase='';
452:  cancelAnimationFrame(miniRaf);miniRaf=0;miniDrag=null;miniKeys.clear();keys.clear();
453:  miniShade.classList.remove('open');miniShade.setAttribute('aria-hidden','true');
454:  toast(resultToast||'Back to the yard.');
455: }
456: function handleMiniKeyDown(e){
457:  if(e.key==='Escape'){e.preventDefault();closeMiniGame();return}
458:  if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','a','d','w','s'].includes(e.key)){e.preventDefault();miniKeys.add(e.key);return}
459:  if(e.key===' '||e.key==='Enter'){if(e.target&&e.target.tagName==='BUTTON')return;e.preventDefault();if(!e.repeat)miniPrimaryAction()}
460: }
461: function miniLoop(now){
462:  if(!miniGame.active)return;
463:  const dt=Math.min(.05,Math.max(0,(now-miniGame.last)/1000));miniGame.last=now;miniGame.time+=dt;
464:  if(miniGame.type==='sandcastle')updateSandcastle(dt);else updateFetch(dt);
465:  drawMiniGame();
466:  if(miniGame.active)miniRaf=requestAnimationFrame(miniLoop);
467: }
468: function miniPrimaryAction(){
469:  if(!miniGame.active)return;
470:  if(miniGame.phase==='result'){closeMiniGame();return}
471:  if(miniGame.type==='sandcastle'){if(miniGame.phase==='drop')dropSand();return}
472:  if(fetchMini.phase==='aim')throwFetch();
473:  else if(fetchMini.phase==='returning'&&!fetchMini.praiseUsed)praiseCharlie();
474:  else if(fetchMini.phase==='roundEnd')fetchMini.endingTimer=0;
475: }
