477:  if(scene!=='yard'){toast('The sandbox is in the backyard.');return}
478:  if(!girlsOutside){toast('Call the girls outside first—or play fetch with Charlie.');return}
479:  if(sandboxPlayed){toast('The girls already had their sandbox time this visit.');return}
