159:  function updateMealUrgency(){
160:    const dayMinutes=scheduledDayMinutes();
161:    for(const meal of ['lunch','dinner']){
162:     const state=mealUrgency[meal];
163:     if(!tasks[meal]&&!state.warned&&dayMinutes>=state.due-30){
164:      state.warned=true;
165:      toast(`Almost time for ${meal}! Let’s get it ready.`);
166:     }
167:    }
168:    for(const meal of ['lunch','dinner']){
169:     if(tasks[meal])continue;
170:     const state=mealUrgency[meal];
171:     if(dayMinutes>=state.due&&state.lateStarted===null)state.lateStarted=elapsed;
172:     if(state.lateStarted===null)continue;
173:     const late=elapsed-state.lateStarted;
174:     if(late>=35&&!state.lateWarned){
175:      state.lateWarned=true;
176:      temper=Math.max(0,temper-4);focus=Math.max(0,focus-3);stressLeft=Math.max(stressLeft,3);
177:      toast(`It’s getting late for ${meal}. The girls are getting cranky!`);
178:     }
179:     const step=Math.floor(Math.max(0,late-20)/12);
180:     if(step>state.penaltyStep){
181:      const stepIncrease=step-state.penaltyStep;
182:      temper=Math.max(0,temper-1.5*stepIncrease);focus=Math.max(0,focus-1*stepIncrease);stressLeft=Math.max(stressLeft,2);
