const { launch } = require('/home/runner/work/PlayGround/PlayGround/tests/browser');
const URL = (process.env.BASE_URL || 'http://localhost:3002') + '/index.html?debug=1&v=' + Date.now();
(async () => {
  const browser = await launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  page.on('pageerror', e => console.log('PAGEERROR', String(e)));
  await page.goto(URL, { waitUntil: 'load' });
  await page.click('#startGame');
  await page.waitForFunction(() => window.__game && __game.state().opening === false, { timeout: 30000 });
  const dlgOpen = await page.evaluate(() => document.querySelector('#dialogShade').classList.contains('open'));
  if (dlgOpen) {
    const labels = await page.evaluate(() => [...document.querySelectorAll('#dialogChoices button')].map(b => b.textContent));
    const idx = labels.findIndex(t => /bed/i.test(t));
    await page.evaluate(i => document.querySelectorAll('#dialogChoices button')[i].click(), idx >= 0 ? idx : 0);
  }
  await page.waitForFunction(() => !__game.state().paused, { timeout: 5000 });
  await page.evaluate(() => {
    const c = __game.girls.find(g => g.dog);
    c.speed = 130;
    __game.charlieTimer.action = 'zoomies';
    __game.charlieTimer.lastRoom = __game.roomAt(c.x, c.y);
    __game.charlieTimer.zoomieRooms = new Set([__game.charlieTimer.lastRoom]);
    __game.setMultiDestination(c, [[180, 225], [440, 225], [300, 350], [230, 550], [560, 550], [800, 550]], 'charlie-zoomies');
  });
  for (let i = 0; i < 120; i++) {
    await page.waitForTimeout(100);
    const info = await page.evaluate(() => {
      const c = __game.girls.find(g => g.dog);
      return { room: __game.roomAt(c.x, c.y), rooms: [...__game.charlieTimer.zoomieRooms], action: __game.charlieTimer.action, x: Math.round(c.x), y: Math.round(c.y), rl: c.route ? c.route.length : 0, next: c.route && c.route[0] ? c.route[0].map(Math.round) : null };
    });
    console.log(i, JSON.stringify(info));
    if (info.rooms.length >= 5) { console.log('DONE'); break; }
    if (info.action !== 'zoomies') { console.log('ENDED action', info.action); break; }
  }
  await browser.close();
})();

