const { launch } = require('/home/runner/work/PlayGround/PlayGround/tests/browser');
const URL = (process.env.BASE_URL || 'http://localhost:3002') + '/index.html?debug=1&v=' + Date.now();
(async () => {
  const browser = await launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  page.on('pageerror', e => console.log('PAGEERROR', String(e)));
  await page.goto(URL, { waitUntil: 'load' });
  await page.click('#startGame');
  await page.waitForFunction(() => window.__game && __game.state().opening === false, { timeout: 30000 });
  const dlgOpen = await page.evaluate(() => document.querySelector('#dialogShade').classList.contains('open'));
  if (dlgOpen) await page.evaluate(() => document.querySelectorAll('#dialogChoices button')[0].click());
  await page.waitForFunction(() => !__game.state().paused, { timeout: 5000 });
  await page.evaluate(() => {
    const g = __game.girls.find(x => x.short === 'Ellerle');
    g.asleep = false; g.speed = 120; g.x = 445; g.y = 176;
    __game.setDestination(g, 435, 217, 'bedEllerle');
  });
  const first = await page.evaluate(() => {
    const g = __game.girls.find(x => x.short === 'Ellerle');
    return g.route;
  });
  console.log('ROUTE', JSON.stringify(first));
  for (let i = 0; i < 40; i++) {
    await page.waitForTimeout(200);
    const s = await page.evaluate(() => {
      const g = __game.girls.find(x => x.short === 'Ellerle');
      return { x: Math.round(g.x), y: Math.round(g.y), rl: g.route ? g.route.length : 0, next: g.route && g.route[0] ? g.route[0].map(Math.round) : null, mode: g.routeMode, bed: __game.tasks.bedEllerle, stuck: Math.round((g.stuckTime || 0) * 10) / 10, agenda: g.agenda };
    });
    console.log(i, JSON.stringify(s));
    if (s.bed) { console.log('ARRIVED'); break; }
  }
  await browser.close();
})();

