  function housePath(x1,y1,x2,y2,g){const cell=14,minX=32,minY=32,cols=67,rows=46,fx=i=>minX+i*cell,fy=j=>minY+j*cell,key=(i,j)=>j*cols+i;const free=new Uint8Array(cols*rows);for(let j=0;j<rows;j++)for(let i=0;i<cols;i++)free[key(i,j)]=(fx(i)<=966&&fy(j)<=666&&!blocked(fx(i),fy(j),g))?1:0;const near=(x,y)=>{let best=-1,bd=Infinity;for(let j=0;j<rows;j++)for(let i=0;i<cols;i++){if(!free[key(i,j)])continue;const d=(fx(i)-x)**2+(fy(j)-y)**2;if(d<bd){bd=d;best=key(i,j)}}return best};const s=near(x1,y1),goal=near(x2,y2);if(s<0||goal<0)return null;const prev=new Int32Array(cols*rows).fill(-1),seen=new Uint8Array(cols*rows),q=[s];seen[s]=1;let found=false;for(let head=0;head<q.length;head++){const cur=q[head];if(cur===goal){found=true;break}const i=cur%cols,j=(cur-i)/cols;for(let dj=-1;dj<=1;dj++)for(let di=-1;di<=1;di++){if(!di&&!dj)continue;const ni=i+di,nj=j+dj;if(ni<0||nj<0||ni>=cols||nj>=rows)continue;const nk=key(ni,nj);if(seen[nk]||!free[nk])continue;if(di&&dj&&(!free[key(i+di,j)]||!free[key(i,j+dj)]))continue;seen[nk]=1;prev[nk]=cur;q.push(nk)}}if(!found)return null;const cells=[];for(let c=goal;c!==s&&c>=0;c=prev[c])cells.push([fx(c%cols),fy((c-c%cols)/cols)]);cells.reverse();const pts=[];let cx=x1,cy=y1;for(let i=0;i<cells.length;i++){if(i===cells.length-1||!segmentClear(cx,cy,cells[i+1][0],cells[i+1][1],g)){pts.push(cells[i]);[cx,cy]=cells[i]}}if(segmentClear(cx,cy,x2,y2,g))pts.push([x2,y2]);else pts.push(nearestOpen(x2,y2,g));return pts}

