161:  function updateMealUrgency(){
162:    const dayMinutes=scheduledDayMinutes();
163:    for(const meal of ['lunch','dinner']){
164:     const state=mealUrgency[meal];
165:     if(!tasks[meal]&&!state.warned&&dayMinutes>=state.due-30){
166:      state.warned=true;
167:      toast(`Almost time for ${meal}! Let’s get it ready.`);
168:     }
169:    }
170:    for(const meal of ['lunch','dinner']){
171:     if(tasks[meal])continue;
172:     const state=mealUrgency[meal];
173:     if(dayMinutes>=state.due&&state.lateStarted===null)state.lateStarted=elapsed;
174:     if(state.lateStarted===null)continue;
175:     const late=elapsed-state.lateStarted;
176:     if(late>=35&&!state.lateWarned){
177:      state.lateWarned=true;
178:      temper=Math.max(0,temper-4);focus=Math.max(0,focus-3);stressLeft=Math.max(stressLeft,3);
179:      toast(`It’s getting late for ${meal}. The girls are getting cranky!`);
180:     }
181:     const step=Math.floor(Math.max(0,late-20)/12);
182:     if(step>state.penaltyStep){
183:      const stepIncrease=step-state.penaltyStep;
