ft,2.5);wanderGirl(g,task,true)}else{g.callStatus='refusing';g.bubble=g.age<=6?'No, I’m busy!':g.age<=10?'Do I have to right now?':'Can I finish this first?';g.bubbleLeft=3.2;g.agenda='politely stalling Dad';temper=Math.max(0,temper-2);focus=Math.max(0,focus-.6);stressLeft=Math.max(stressLeft,2.5)}})}
