const { launch } = require('./browser');
const { spawn } = require('child_process');

(async () => {
  const server = spawn('python3', ['-m', 'http.server', '3007'], { stdio: 'ignore' });
  await new Promise(r => setTimeout(r, 1200));
  const browser = await launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  await page.goto('http://localhost:3007/index.html?debug=1&v=' + Date.now());
  await page.waitForFunction(() => window.__game, { timeout: 30000 });
  await page.click('#startGame');
  await page.waitForFunction(() => window.__game.state().opening === false, { timeout: 30000 });
  if (await page.evaluate(() => document.querySelector('#dialogShade').classList.contains('open')))
    await page.evaluate(() => document.querySelector('#dialogChoices button').click());
  await page.waitForFunction(() => !__game.state().paused, { timeout: 5000 });
  await page.evaluate(() => { __game.player.x = 500; __game.player.y = 430; });
  await page.waitForTimeout(400);
  await page.screenshot({ path: '/tmp/opencode/kitchen.png' });
  await browser.close();
  server.kill();
})().catch(e => { console.error(e); process.exit(1); });

